const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry for Salta Province, Argentina
  const salta = ee.Geometry.Polygon([
    [[-68.0, -22.0], [-62.0, -22.0], [-62.0, -26.0], [-68.0, -26.0], [-68.0, -22.0]]
  ]);

  // 2. Data Acquisition - MODIS NDVI for vegetation monitoring
  const modis2000 = ee.ImageCollection('MODIS/006/MOD13Q1')
    .filterDate('2000-12-01', '2001-02-28')
    .filterBounds(salta)
    .select('NDVI');

  const modis2019 = ee.ImageCollection('MODIS/006/MOD13Q1')
    .filterDate('2019-12-01', '2020-02-28')
    .filterBounds(salta)
    .select('NDVI');

  // Check collection sizes
  const count2000 = modis2000.size().getInfo();
  const count2019 = modis2019.size().getInfo();

  console.log(`2000 Images: ${count2000}, 2019 Images: ${count2019}`);

  if (count2000 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create mean composites
  const ndvi2000 = modis2000.mean().multiply(0.0001); // Scale factor
  const ndvi2019 = modis2019.mean().multiply(0.0001);

  // 4. Calculate mean NDVI values
  const stats2000 = ndvi2000.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: salta,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2019 = ndvi2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: salta,
    scale: 1000,
    maxPixels: 1e9
  });

  const ndviVal2000 = stats2000.get('NDVI').getInfo();
  const ndviVal2019 = stats2019.get('NDVI').getInfo();

  // Check for valid pixels
  const pixelCount2000 = ndvi2000.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: salta,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const pixelCount2019 = ndvi2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: salta,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`2000 NDVI: ${ndviVal2000?.toFixed(4)}, Pixels: ${pixelCount2000}`);
  console.log(`2019 NDVI: ${ndviVal2019?.toFixed(4)}, Pixels: ${pixelCount2019}`);

  // 5. Validation & Final Answer
  if (pixelCount2000 === 0 || pixelCount2019 === 0) {
    console.log("<answer>C2</answer>");
  } else if (ndviVal2000 === null || ndviVal2019 === null || 
             isNaN(ndviVal2000) || isNaN(ndviVal2019)) {
    console.log("<answer>C3</answer>");
  } else if (ndviVal2019 < ndviVal2000) {
    console.log(`Forest cover decreased: ${(ndviVal2000 - ndviVal2019).toFixed(4)} NDVI`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Forest cover stable/increased: ${(ndviVal2019 - ndviVal2000).toFixed(4)} NDVI`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
